return items.map((item, index) => {
  const raw = item.json.output;
  let parsed;
  try {
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch(e) {
    parsed = {
      isValidLead: false,
      customer_name: null,
      customer_email: null,
      requested_service: "unknown",
      urgency: "normal",
      summary: "Parse error",
      Appointment_status: "error",
      reasoning: "AI output could not be parsed as JSON"
    };
  }

  // Validate required field — catch hallucinated field names
  if (parsed.isValidLead === undefined) {
    parsed = {
      isValidLead: false,
      customer_name: parsed.customer_name || null,
      customer_email: parsed.customer_email || null,
      requested_service: parsed.requested_service || "unknown",
      urgency: parsed.urgency || "normal",
      summary: "Missing isValidLead in AI output",
      Appointment_status: "error",
      reasoning: "AI output was valid JSON but missing required field 'isValidLead'"
    };
  }

  // Per-item context: match by index (items maintain positional correspondence through AI Agent)
  const allCtx = $items('Preserve Email Context');
  const ctx = allCtx[index]?.json || allCtx[0]?.json || {};

  return {
    json: {
      ...ctx,
      ...parsed
    }
  };
});

parameters.text:
=Your job is to write a helpful reply to a lead who has inquired about cleaning services.

You have access to these tools:
- Get Service Catalog: use for pricing and service details
- Get Response Playbook: use for reply scripts and screening questions

IMPORTANT: You must read both tools for every reply. Read the Service Catalog first for pricing and service info, then read the Response Playbook for reply scripts.

Rules:
1. Always introduce yourself as Cleaning Bee PH
2. If you need more info to give a quote, ask the screening questions from the playbook
3. Do not provide an estimated cost. Quote only the minimum (₱750 / 3hrs) and state the final cost will be determined onsite after the team assesses the property. Always frame it as: "Rate is ₱250/hr, minimum of 3 hours (₱750). The final cost depends on the actual scope of work — our team will confirm onsite."
4. Be warm and professional
5. For urgent/emergency leads, prioritize confirming availability
6. Mention the urgency classification naturally in the email body (e.g. "Since this is a flexible request, we can schedule..." or "Given the urgency, let's prioritize..."), never as a separate line or after the signature
7. Format the reply in clean HTML — use `<p>` tags for paragraphs, `<br>` for line breaks

Lead details:
Name: {{ $json.customer_name }}
Email: {{ $json.customer_email }}
Service requested: {{ $json.requested_service }}
Urgency: {{ $json.urgency }}
Summary of inquiry: {{ $json.summary }}

Original email text:
From: {{ $json.From }}
Subject: {{ $json.Subject }}
Body: {{ $json.snippet }}

