return items.map((item, index) => {
  const output = item.json.output;
  const reply_body = typeof output === 'string'
    ? output
    : JSON.stringify(output);

  // Per-item context: match by index (items maintain positional correspondence through AI Agent)
  const allCtx = $items('Save Lead Context');
  const ctx = allCtx[index]?.json || allCtx[0]?.json || {};

  return {
    json: {
      ...ctx,
      reply_body
    }
  };
});

return items.map((item, index) => {
  const rows = item.json.rows || [];
  const row = rows[0] || {};

  const allCtx = $items('Preserve Email Context');
  const ctx = allCtx[index]?.json || allCtx[0]?.json || {};

  const email = row.Email || ctx.senderEmail || '';
  const rawText = ctx.text || '';
  const threadId = ctx.threadId || ctx.id || '';

  const cleanedBody = rawText
    .split(/\n\s*On\s.*?wrote:\s*\n/)[0]
    .replace(/^[\s]*>.*$/gm, '')
    .trim();

  return {
    json: { Email: email, cleanedBody, threadId }
  };
});

return items.map((item, index) => {
  const raw = item.json.output;
  let parsed;
  try {
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch(e) {
    parsed = {
      appointment_date: null,
      start_time: null,
      end_time: null,
      duration_hours: 3,
      confirmation_email_html: "<p>Sorry, we encountered an error scheduling your appointment. Please contact us directly.</p>",
      event_summary: "Cleaning Bee PH - Appointment",
      event_description: "Scheduling error - manual review needed",
      Appointment_status: "error",
      _parseError: true
    };
  }

  // Validate required fields
  const required = ['appointment_date', 'start_time', 'end_time', 'confirmation_email_html'];
  for (const field of required) {
    if (!parsed[field]) {
      parsed.Appointment_status = "error";
      parsed._validationError = `Missing required field: ${field}`;
      break;
    }
  }

  // Validate time format (HH:MM or H:MM — pad single-digit hours)
  if (!parsed._validationError && parsed.start_time) {
    const timeMatch = /^(\d{1,2}):(\d{2})$/.exec(parsed.start_time);
    if (timeMatch) {
      parsed.start_time = timeMatch[1].padStart(2, '0') + ':' + timeMatch[2];
    } else {
      parsed.Appointment_status = "error";
      parsed._validationError = `Invalid start_time format: ${parsed.start_time}. Expected HH:MM`;
    }
  }
  if (!parsed._validationError && parsed.end_time) {
    const timeMatch = /^(\d{1,2}):(\d{2})$/.exec(parsed.end_time);
    if (timeMatch) {
      parsed.end_time = timeMatch[1].padStart(2, '0') + ':' + timeMatch[2];
    } else {
      parsed.Appointment_status = "error";
      parsed._validationError = `Invalid end_time format: ${parsed.end_time}. Expected HH:MM`;
    }
  }

  // Per-item context: match by index (items maintain positional correspondence through AI Agent)
  const allCtx = $items('Save Scheduling Context');
  const ctx = allCtx[index]?.json || allCtx[0]?.json || {};

  return {
    json: {
      ...ctx,
      ...parsed,
      Appointment_status: parsed._parseError || parsed._validationError ? "error" : "scheduled"
    }
  };
});

return items.map(item => {
  const from = item.json.From || item.json.from || '';
  let senderEmail = '';

  if (typeof from === 'object' && from.text) {
    // Simplify OFF — from is { value, html, text }
    const match = from.text.match(/<([^>]+)>/);
    senderEmail = match ? match[1] : from.text.trim();
  } else if (typeof from === 'string') {
    // Simplify ON — from is "Name <email>" or "From: Name <email>"
    const match = from.match(/<([^>]+)>/);
    senderEmail = match ? match[1] : from.trim();
  }

  return { json: { ...item.json, senderEmail } };
});
